(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(x*0.012+t*0.25)*20 + Math.cos(y*0.018-t*0.3)*12;
  const warp1y = Math.cos(y*0.014+t*0.2)*18 + Math.sin(x*0.016-t*0.28)*14;
  const warp2x = Math.sin((x+warp1x)*0.008+t*0.15)*25 + Math.cos((y+warp1y)*0.01-t*0.18)*15;
  const warp2y = Math.cos((y+warp1y)*0.009-t*0.12)*22 + Math.sin((x+warp1x)*0.011+t*0.16)*13;
  const sx = x + warp1x + warp2x, sy = y + warp1y + warp2y;
  const src = [
    [120+Math.sin(t*0.4)*90, 60+Math.cos(t*0.3)*40, 0.065, 2.1, 0.7],
    [360+Math.cos(t*0.5)*80, 50+Math.sin(t*0.6)*35, 0.08, 1.8, -0.5],
    [240+Math.sin(t*0.3+1.5)*130, 120+Math.cos(t*0.4+0.8)*80, 0.05, 2.5, 0.3],
    [80+Math.cos(t*0.7+2)*70, 190+Math.sin(t*0.5+1)*55, 0.09, 1.6, -0.8],
    [400+Math.sin(t*0.35+3)*75, 180+Math.cos(t*0.55+2)*65, 0.07, 2.3, 0.6],
    [200+Math.cos(t*0.45+4)*100, 220+Math.sin(t*0.65)*70, 0.075, 2.0, -0.3],
    [300+Math.sin(t*0.28+5)*110, 30+Math.cos(t*0.48+3)*50, 0.055, 2.7, 0.4],
    [160+Math.cos(t*0.6+1)*60, 140+Math.sin(t*0.42+4)*60, 0.085, 1.9, -0.6]
  ];
  let act = 0, inh = 0, feed = 0;
  for (const [sX, sY, f, sp, ph] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp + ph);
    act += wave;
    inh += Math.sin(d*f*0.65 + t*sp*0.55 + ph*1.3 + 2.0);
    feed += Math.sin(d*f*1.2 - t*sp*0.8 + ph*0.7 + 4.0) * 0.5;
  }
  act /= 8; inh /= 8; feed /= 8;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*0.95);
  const bg3 = Math.sin((sx+sy)*0.1+t*2.2)*0.25;
  const bg4 = Math.sin((sx-sy)*0.08-t*1.8)*0.25;
  const bg = (bg1+bg2)/2 + bg3 + bg4;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.0)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const lapAct = Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.08+t)*0.4;
  const lapInh = Math.cos(sx*0.12+sy*0.09-t*0.6)*Math.cos(sx*0.09-sy*0.12+t*0.4);
  const reaction = Math.tanh((act*1.1 - inh*0.75 + feed*0.4 + bg*0.25 + spiral*0.35 + lapAct*0.3 - lapInh*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.13+0.5)*Math.sin(sy*0.13-0.3) + Math.sin((sx-sy)*0.09+t*0.8)*0.4)*1.4)*0.25;
  const micro = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.4-t*2.5)*0.08;
  const blend = reaction*0.7 + cell*0.22 + micro;
  const v = blend*0.5+0.5;
  const breathe = 0.92 + Math.sin(t*0.4)*0.08;
  const lum = (0.82 + Math.sin(reaction*Math.PI)*0.18) * breathe;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + (Math.abs(reaction)-0.65)*0.6 : 1.0;
  const glow = Math.max(0, 1.0-Math.abs(reaction)*1.8)*0.15;
  const pal = [
    [5,12,52],[8,35,82],[12,68,108],[18,112,128],[35,155,138],
    [120,185,120],[195,200,75],[220,175,60],[215,130,65],
    [195,80,70],[160,50,80],[100,28,72],[45,15,58],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const r = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const highlight = Math.max(0, reaction-0.5)*40;
  return [
    Math.min(255, ((r+glow*80+highlight)*lum*edge)|0),
    Math.min(255, ((g+glow*100+highlight*0.7)*lum*edge)|0),
    Math.min(255, ((b+glow*120+highlight*0.3)*lum*edge)|0)
  ];
}
